83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
