108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        if (!normalizeNewOwner(owner)) {
114	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
115	        }
116	        if (dailyLimitReached(owner.getRegistrationDate())) {
117	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
118	        }
119	        if (cityIsAtCapacity(owner.getCity())) {
120	            return new ResponseEntity<>(HttpStatus.CONFLICT);
121	        }
122	        owner.setHouseholdId(owner.computeHouseholdId());
123	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
124	        Optional<Owner> householdMember = findHouseholdMember(owner);
125	        if (householdMember.isPresent() && !sharesHousehold) {
126	            return new ResponseEntity<>(HttpStatus.CONFLICT);
127	        }
128	        boolean declaredHouseholdMember = householdMember.isPresent();
129	        assignDerivedAttributes(owner, declaredHouseholdMember);
130	        this.clinicService.saveOwner(owner);
131	        auditOwnerCreated(owner);
132	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
133	        headers.setLocation(UriComponentsBuilder.newInstance()
134	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
135	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
