221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
224	        Owner owner = this.clinicService.findOwnerById(ownerId);
225	        if (owner != null) {
226	            Pet pet = owner.getPet(petId);
227	            if (pet != null) {
228	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
229	            }
230	        }
231	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
232	    }
233	
234	    /**
235	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
236	     * the canonical form each stored value must take: the address is trimmed,
237	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
238	     * telephone is converted to E.164, any email is lower-cased and a missing
239	     * registration date defaults to today. Field-level rejections are reported here
240	     * rather than inline in {@link #addOwner}, and normalisation runs before any
241	     * household comparison so those comparisons see the canonical values.
242	     *
243	     * @param owner the freshly-mapped owner to normalise
244	     * @return {@code true} if the fields are valid, or {@code false} if the address
245	     *         is blank after normalisation, the telephone cannot form a valid
246	     *         E.164 number, or a supplied registration date is later than the
247	     *         server date, in which case the request must be rejected with
248	     *         {@code 400 Bad Request}
249	     */
250	    private boolean normalizeNewOwner(Owner owner) {
251	        if (!normalizeAddressFields(owner)) {
252	            return false;
253	        }
254	        String telephone = Telephones.toE164(owner.getTelephone());
255	        if (telephone == null) {
256	            return false;
257	        }
258	        owner.setTelephone(telephone);
259	        if (owner.getEmail() != null) {
260	            String email = owner.getEmail().toLowerCase();
261	            owner.setEmail(email);
262	            if (emailDomainIsBlocked(email)) {
263	                return false;
264	            }
265	        }
266	        if (!owner.postcodeValidForLocality()) {
267	            return false;
268	        }
269	        if (owner.getRegistrationDate() == null) {
270	            owner.setRegistrationDate(LocalDate.now());
271	        } else if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
272	            return false;
273	        }
274	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
275	        return true;
276	    }
277	
278	    /**
279	     * Normalise the owner's address fields in place to their canonical stored form
280	     * (trimmed, whitespace-collapsed, upper-cased and with common abbreviations
281	     * expanded; see {@link Owner#normalizeAddress(String)}), gathering the whole address
282	     * concern of {@link #normalizeNewOwner} in one place. The structured form is
283	     * preferred: when a non-blank {@code addressLine1} is supplied it (and any
284	     * {@code addressLine2}) is normalised, and the flat {@code address} is composed from
285	     * them — the normalised {@code addressLine1}, with a single space and the normalised
286	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the
287	     * flat {@code address} is normalised on its own, preserving backward compatibility.
288	     * Either way the canonicalised values are written back so every later household
289	     * comparison and read sees them.
290	     *
291	     * @param owner the freshly-mapped owner whose address fields are being normalised
292	     * @return {@code true} once an address is valid and stored, or {@code false} when
293	     *         neither a structured {@code addressLine1} nor a flat {@code address} is
294	     *         present after normalisation, in which case the request must be rejected
295	     *         with {@code 400 Bad Request}
296	     */
297	    private boolean normalizeAddressFields(Owner owner) {
298	        String addressLine1 = Owner.normalizeAddress(owner.getAddressLine1());
299	        if (!addressLine1.isEmpty()) {
300	            owner.setAddressLine1(addressLine1);
301	            String composed = addressLine1;
302	            String addressLine2 = Owner.normalizeAddress(owner.getAddressLine2());
303	            if (!addressLine2.isEmpty()) {
304	                owner.setAddressLine2(addressLine2);
305	                composed = addressLine1 + " " + addressLine2;
306	            }
307	            owner.setAddress(composed);
308	            return true;
309	        }
310	        String address = Owner.normalizeAddress(owner.getAddress());
311	        if (address.isEmpty()) {
312	            return false;
313	        }
314	        owner.setAddress(address);
315	        return true;
316	    }
317	
318	    /**
319	     * Email domains that identify disposable, throw-away mailboxes. An owner whose
320	     * email address is on one of these domains is rejected with {@code 400 Bad
321	     * Request} rather than created.
322	     */
323	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
324	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
325	
326	    /**
327	     * Whether the given (already lower-cased) email address belongs to a disposable
328	     * mailbox domain on the blocklist. The domain is the part after the final
329	     * {@code '@'}; an address without one is treated as having no blocked domain.
330	     *
331	     * @param email the owner's normalised (lower-cased) email address
332	     * @return {@code true} if the email's domain is on the disposable-domain blocklist
333	     */
334	    private static boolean emailDomainIsBlocked(String email) {
335	        int at = email.lastIndexOf('@');
336	        if (at < 0) {
337	            return false;
338	        }
339	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
340	    }
341	
342	    /**
343	     * The fixed list of public holidays on which the clinic is closed. A registration
344	     * date that lands on one of these dates is treated the same as a weekend and rolled
345	     * forward past it (see {@link #rollToBusinessDay(LocalDate)}).
346	     */
347	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
348	        LocalDate.of(2026, 1, 1),
349	        LocalDate.of(2026, 1, 26),
350	        LocalDate.of(2026, 4, 25),
351	        LocalDate.of(2026, 12, 25),
352	        LocalDate.of(2026, 12, 28));
353	
354	    /**
355	     * Roll the given date forward to the next business day when it falls on a weekend or
356	     * a listed public holiday: a Saturday, Sunday or public holiday is advanced one day
357	     * at a time until a non-holiday weekday is reached, while a plain business day is
358	     * returned unchanged. Because rolling off a weekend can land on a holiday (and vice
359	     * versa), the advance repeats until the date is neither. Applied to the effective
360	     * registration date (whether supplied in the request or defaulted to the server date)
361	     * so that every value derived from it uses the adjusted business day.
362	     *
363	     * @param date the effective registration date
364	     * @return the same date if it is a non-holiday weekday, otherwise the next such day
365	     */
366	    private static LocalDate rollToBusinessDay(LocalDate date) {
367	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
368	            date = date.plusDays(1);
369	        }
370	        return date;
371	    }
372	
373	    /**
374	     * Whether the given date falls on a weekend (Saturday or Sunday).
375	     */
376	    private static boolean isWeekend(LocalDate date) {
377	        return switch (date.getDayOfWeek()) {
378	            case SATURDAY, SUNDAY -> true;
379	            default -> false;
380	        };
381	    }
382	
383	    /**
384	     * Find an existing owner that belongs to the same household as the given owner,
385	     * i.e. shares the same last name (compared case-insensitively with runs of
386	     * whitespace collapsed to a single space) and postcode, and so resolves to the same
387	     * deterministic {@code householdId}.
388	     *
389	     * @param owner the candidate owner being created
390	     * @return the matching existing owner, or empty if none exists
391	     */
392	    private Optional<Owner> findHouseholdMember(Owner owner) {
393	        return this.clinicService.findAllOwners().stream()
394	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()))
395	            .filter(existing -> existing.sameHouseholdAs(owner))
396	            .findFirst();
397	    }
398	
399	    /**
400	     * Assign the owner's computed-at-creation attributes in place: its customer code,
401	     * namesake count, membership number, bulk-signup warning and household size. Unlike
402	     * the {@code @Transient} attributes {@link Owner} recomputes on demand, these are
403	     * derived once here — from the owner's own (already normalised) fields and from the
404	     * wider owner population — and persisted with the owner. Run after normalisation,
405	     * household resolution and the identity-key check, so every value reflects the
406	     * owner's final field values and any household it has joined, and immediately before
407	     * the owner is saved.
408	     *
409	     * <p>Ordering matters: the customer code is assigned first because the membership
410	     * number is built from it.
411	     *
412	     * @param owner the candidate owner being created, after household resolution
413	     * @param declaredHouseholdMember whether this owner was created as a declared member
414	     *                                of an existing household (it shared an existing
415	     *                                owner's household and set {@code sharesHousehold}),
416	     *                                in which case it is not a suspected duplicate
417	     */
418	    private void assignDerivedAttributes(Owner owner, boolean declaredHouseholdMember) {
419	        owner.setCustomerCode(deduplicatedCustomerCode(owner));
420	        owner.setNamesakeCount(countNamesakes(owner));
421	        owner.setMembershipNumber(owner.computeMembershipNumber());
422	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
423	        owner.setHouseholdSize(householdSize(owner));
424	        assignPossibleDuplicate(owner, declaredHouseholdMember);
425	    }
426	
427	    /**
428	     * Compute the customer code to assign to the candidate owner, de-duplicated against
429	     * every existing owner's customer code. The base code is the owner's computed
430	     * {@code <REGION>-<HASH8>} (see {@link Owner#computeCustomerCode()}); when it does not
431	     * already belong to an existing owner it is used unchanged. Otherwise it collides, and
432	     * {@code -<n>} is appended with the smallest integer {@code n} of 2 or more that yields
433	     * a code no existing owner holds, so the returned customer code is unique. Evaluated
434	     * before the owner is saved, so only pre-existing owners are considered.
435	     *
436	     * @param owner the candidate owner being created, after normalisation
437	     * @return the unique (de-duplicated) customer code to assign
438	     */
439	    private String deduplicatedCustomerCode(Owner owner) {
440	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
441	            .map(Owner::getCustomerCode)
442	            .filter(code -> code != null)
443	            .collect(java.util.stream.Collectors.toSet());
444	        String base = owner.computeCustomerCode();
445	        if (!existingCodes.contains(base)) {
446	            return base;
447	        }
448	        int n = 2;
449	        while (existingCodes.contains(base + "-" + n)) {
450	            n++;
451	        }
452	        return base + "-" + n;
453	    }
454	
455	    /**
456	     * Flag the candidate owner as a possible duplicate of an existing owner. A soft
457	     * match is an existing owner that shares this owner's last name (compared
458	     * case-insensitively) and postcode but carries a different (normalised) telephone.
459	     * When such a match exists the owner is still created, but with
460	     * {@code possibleDuplicate} true and {@code possibleDuplicateOf} set to the matching
461	     * owner's id; otherwise {@code possibleDuplicate} is false and no match id is
462	     * recorded. The earliest-created matching owner (lowest id) is chosen so the result
463	     * is deterministic. Evaluated before the owner is saved, so only pre-existing owners
464	     * are considered.
465	     *
466	     * <p>A declared household member — one that shared an existing owner's household
467	     * (same last name and postcode) and was admitted because it set
468	     * {@code sharesHousehold} — is never flagged: a declared member is not a suspected
469	     * duplicate, so its {@code possibleDuplicate} is false with no match id.
470	     *
471	     * @param owner the candidate owner being created, after household resolution
472	     * @param declaredHouseholdMember whether the owner is a declared household member
473	     */
474	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
475	        if (declaredHouseholdMember) {
476	            owner.setPossibleDuplicate(false);
477	            owner.setPossibleDuplicateOf(null);
478	            return;
479	        }
480	        String lastName = normalizeName(owner.getLastName());
481	        String postcode = owner.getPostcode();
482	        String telephone = owner.getTelephone();
483	        Optional<Owner> match = this.clinicService.findAllOwners().stream()
484	            .filter(existing -> postcode != null && postcode.equals(existing.getPostcode())
485	                && normalizeName(existing.getLastName()).equals(lastName)
486	                && telephone != null && !telephone.equals(existing.getTelephone()))
487	            .min(Comparator.comparing(Owner::getId));
488	        if (match.isPresent()) {
489	            owner.setPossibleDuplicate(true);
490	            owner.setPossibleDuplicateOf(match.get().getId());
491	        } else {
492	            owner.setPossibleDuplicate(false);
493	            owner.setPossibleDuplicateOf(null);
494	        }
495	    }
496	
497	    /**
498	     * Count how many owners belong to the given owner's household once this create
499	     * completes: the owners that already share its deterministic {@code householdId}
500	     * (derived from last name and postcode) plus the owner being created. Evaluated
501	     * after the owner's {@code householdId} has been assigned. An owner whose
502	     * {@code householdId} matches no existing owner is a household of one.
503	     *
504	     * @param owner the candidate owner being created, after household resolution
505	     * @return the household member count after this create (at least {@code 1})
506	     */
507	    private int householdSize(Owner owner) {
508	        String householdId = owner.getHouseholdId();
509	        if (householdId == null) {
510	            return 1;
511	        }
512	        long existing = this.clinicService.findAllOwners().stream()
513	            .filter(other -> householdId.equals(other.getHouseholdId()))
514	            .count();
515	        return (int) existing + 1;
516	    }
517	
518	    /**
519	     * Count the existing owners that share the given owner's first and last name,
520	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
521	     * before the new owner is saved, so the result reflects only owners that
522	     * already existed at creation time.
523	     *
524	     * @param owner the candidate owner being created
525	     * @return the number of existing namesakes
526	     */
527	    private int countNamesakes(Owner owner) {
528	        String firstName = normalizeName(owner.getFirstName());
529	        String lastName = normalizeName(owner.getLastName());
530	        return (int) this.clinicService.findAllOwners().stream()
531	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
532	                && normalizeName(existing.getLastName()).equals(lastName))
533	            .count();
534	    }
535	
536	    private static String normalizeName(String value) {
537	        return value == null ? "" : value.trim().toLowerCase();
538	    }
539	
540	    /**
541	     * Determine whether the given city has already reached its owner capacity, i.e.
542	     * it already contains 50 or more existing owners (compared case-insensitively
543	     * with surrounding whitespace trimmed). A new owner may not be created in a city
544	     * that is at capacity.
545	     *
546	     * @param city the candidate owner's city
547	     * @return {@code true} if the city already holds 50 or more owners
548	     */
549	    private boolean cityIsAtCapacity(String city) {
550	        String normalizedCity = normalizeName(city);
551	        long count = this.clinicService.findAllOwners().stream()
552	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
553	            .count();
554	        return count >= 50;
555	    }
556	
557	    /**
558	     * Determine whether the daily owner-creation limit has already been reached, i.e.
559	     * 100 or more owners already carry the given registration date. A new owner may
560	     * not be created once that day's cap is reached.
561	     *
562	     * @param registrationDate the registration date the new owner would be created with
563	     * @return {@code true} if 100 or more existing owners share that registration date
564	     */
565	    private boolean dailyLimitReached(LocalDate registrationDate) {
566	        long count = this.clinicService.findAllOwners().stream()
567	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
568	            .count();
569	        return count >= 100;
570	    }
571	
572	    /**
573	     * Determine whether more than 80 owners have already been created for the given
574	     * registration date, i.e. strictly more than 80 existing owners carry that date.
575	     * Evaluated before the new owner is saved, so it reflects only owners that
576	     * already existed at creation time.
577	     *
578	     * @param registrationDate the registration date the new owner would be created with
579	     * @return {@code true} if more than 80 existing owners share that registration date
580	     */
581	    private boolean bulkSignupWarning(LocalDate registrationDate) {
582	        long count = this.clinicService.findAllOwners().stream()
583	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
584	            .count();
585	        return count > 80;
586	    }
587	
588	    /**
589	     * Write the create audit record for a freshly-saved owner. Keeps the audit format in
590	     * one place so it stays in step with the owner's identity: it reports the assigned
591	     * customer code alongside the owner's id, registration date, membership level and
592	     * membership number.
593	     *
594	     * @param owner the owner that has just been created and saved
595	     */
596	    private void auditOwnerCreated(Owner owner) {
597	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
598	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
599	            owner.getMembershipNumber());
600	    }
601	}
