454	     * from its last name and postcode so every owner sharing a last name and postcode
455	     * resolves to the same value. This is the value stored in {@link #getHouseholdId()};
456	     * see {@link OwnerDerivations#householdId(String, String)} for the exact derivation.
457	     *
458	     * @return the household identifier
459	     */
460	    public String computeHouseholdId() {
461	        return OwnerDerivations.householdId(normalize(this.getLastName()), this.postcode);
462	    }
