480	    /**
481	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
482	     * trim, collapse internal runs of whitespace to a single space and lower-case.
483	     */
484	    private static String normalize(String value) {
485	        return OwnerDerivations.collapseWhitespace(value).toLowerCase();
486	    }
487	
